Replace registered_parent_intact (patched_v2/orch_s3h.py 778-786) with an append-only prefix check that persists its baseline once:

```python
P2_START = f'{SHARE}/PARENT2_STARTED'

def _prefix_sha(path, n):
    h = hashlib.sha256(); left = n
    with open(path, 'rb') as fh:
        while left > 0:
            b = fh.read(min(1 << 20, left))
            if not b:
                break
            h.update(b); left -= len(b)
    return h.hexdigest() if left == 0 else None

def registered_parent_intact(item):
    """D11: the registered entry is unchanged and each of its 120 H100 shards still begins with exactly its
    registered bytes. Window 2 may only append (G10' resume appends to 56 of them)."""
    if sha256_file(D11_ENTRY) != D11_ENTRY_SHA:
        halt(item, '登记的 parent_end_of_generation.txt 缺失或已变')
    reg = []
    for line in open(D11_ENTRY):
        parts = line.rstrip('\n').split('  ', 1)
        if len(parts) == 2 and parts[1].startswith(f'{PROJH}/results/rt/s2/'):
            reg.append((parts[0], parts[1]))
    if len(reg) != 120:
        halt(item, f'D11 条目 H100 行数 {len(reg)} != 120')
    if not marker('PARENT2_STARTED'):
        bad = [p for h, p in reg if not os.path.exists(p) or sha256_file(p) != h]
        if bad:
            halt(item, f'第二窗口开始前分片已与 D11 不符（待 leader）: {bad[:5]}')
        rec = {'entry_sha': D11_ENTRY_SHA, 'utc': utc(), 'sizes': {p: os.path.getsize(p) for _, p in reg}}
        try:
            with open(P2_START + '.tmp', 'w') as fh:
                json.dump(rec, fh); fh.flush(); os.fsync(fh.fileno())
            os.replace(P2_START + '.tmp', P2_START)
        except OSError as ex:
            halt(item, f'PARENT2_STARTED 写入失败: {ex}')
        return
    try:
        st = json.load(open(P2_START))
    except Exception as ex:
        halt(item, f'PARENT2_STARTED 读回失败: {ex}')
    sizes = st.get('sizes') or {}
    if st.get('entry_sha') != D11_ENTRY_SHA or set(sizes) != {p for _, p in reg}:
        halt(item, 'PARENT2_STARTED 与 D11 条目不符')
    bad = [p for h, p in reg if not os.path.exists(p) or os.path.getsize(p) < sizes[p]
           or _prefix_sha(p, sizes[p]) != h]
    if bad:
        halt(item, f'登记分片的已登记前缀被改（非追加写，待 leader）: {bad[:5]}')
```

